 88	impl RpcClient {
 89	    /// Sends a request; retries on timeout with exponential backoff.
 90	    pub async fn send(&self, req: Request) -> Result<Response, RpcError> {
 91	        let policy = &self.retry;
 92	        let mut attempt: u32 = 0;
 93	        loop {
 94	            attempt += 1;
 95	            let http = self.build_request(&req)?;
 96	            let timeout = self.config.timeout;
 97	            match self.transport.execute(http, timeout).await {
 98	                Ok(resp) => return Ok(resp),
 99	                Err(RpcError::Timeout) if policy.should_retry(attempt) => {
100	                    let delay = policy.backoff(attempt);
101	                    tracing::warn!(attempt, ?delay, method = %req.method, "rpc timeout; retrying");
102	                    tokio::time::sleep(delay).await;
103	                }
104	                Err(RpcError::Timeout) => {
105	                    return Err(RpcError::Exhausted { attempts: attempt });
106	                }
107	                Err(e) => return Err(e),
108	            }
109	        }
110	    }
